#pragma once

#include <Interpreters/Context_fwd.h>
#include <Processors/QueryPlan/ISourceStep.h>
#include <Processors/QueryPlan/QueryPlan.h>

namespace DB
{

/// Opaque wrapper for the plan generated by a read from a TimeSeries table; the optimizer replaces it
/// with that plan, optimized once under the read's own context (see optimizeTreeSecondPass).
class ReadFromTimeSeriesStep : public ISourceStep
{
public:
    ReadFromTimeSeriesStep(QueryPlanPtr query_plan_, ContextPtr read_context_);

    String getName() const override { return "ReadFromTimeSeries"; }

    void initializePipeline(QueryPipelineBuilder & pipeline, const BuildQueryPipelineSettings &) override;

    QueryPlanPtr extractQueryPlan();

    ContextPtr getReadContext() const { return read_context; }

private:
    QueryPlanPtr query_plan;
    ContextPtr read_context;
};

}
